#include "core.hpp"
#include <algorithm>
#include <array>
#include <cstring>
#include <limits>
#include <sstream>

namespace rescateusb {
namespace {
uint32_t le32(const uint8_t* p){return uint32_t(p[0])|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16)|(uint32_t(p[3])<<24);}
uint64_t le64(const uint8_t* p){return uint64_t(le32(p))|(uint64_t(le32(p+4))<<32);}
struct Gpt {uint64_t current=0,backup=0,first=0,last=0,table=0;uint32_t count=0,entry_size=0,table_crc=0;std::vector<uint8_t> entries;};
bool read_gpt(std::ifstream& file,uint64_t image_size,uint64_t lba,Gpt& g,std::string& error,bool debug){debug_log(debug,"reading GPT header at LBA "+std::to_string(lba));if(lba>std::numeric_limits<uint64_t>::max()/kSectorSize){error="GPT header offset overflow";return false;}std::array<uint8_t,512> h{};if(!read_at(file,lba*kSectorSize,h.data(),h.size())||std::memcmp(h.data(),"EFI PART",8)){error="GPT header signature missing";return false;}uint32_t header_size=le32(h.data()+12),saved_crc=le32(h.data()+16);if(header_size<92||header_size>512){error="Invalid GPT header size";return false;}auto checked=h;std::fill(checked.begin()+16,checked.begin()+20,uint8_t(0));if(crc32(checked.data(),header_size)!=saved_crc){error="GPT header CRC mismatch";return false;}g.current=le64(h.data()+24);g.backup=le64(h.data()+32);g.first=le64(h.data()+40);g.last=le64(h.data()+48);g.table=le64(h.data()+72);g.count=le32(h.data()+80);g.entry_size=le32(h.data()+84);g.table_crc=le32(h.data()+88);uint64_t sectors=image_size/kSectorSize;if(g.current!=lba||g.backup>=sectors||g.backup==g.current){error="GPT current/backup LBA fields invalid";return false;}if(g.first>g.last||g.last>=sectors||g.first<=1){error="GPT usable partition range invalid";return false;}if(g.entry_size<128||g.entry_size%8||!g.count||g.count>16384){error="GPT partition-entry geometry invalid";return false;}uint64_t bytes=uint64_t(g.count)*g.entry_size;if(g.table>std::numeric_limits<uint64_t>::max()/kSectorSize){error="GPT entry-table offset overflow";return false;}uint64_t offset=g.table*kSectorSize;if(offset>image_size||bytes>image_size-offset||bytes>64*1024*1024){error="GPT entry table outside image or too large";return false;}g.entries.resize(size_t(bytes));if(!read_at(file,offset,g.entries.data(),g.entries.size())){error="Cannot read GPT entry table";return false;}if(crc32(g.entries.data(),g.entries.size())!=g.table_crc){error="GPT entry-table CRC mismatch";return false;}return true;}
bool analyze_gpt(std::ifstream& file,Report& report,bool debug){report.format="GPT";Gpt primary,backup;std::string error;if(!read_gpt(file,report.size_bytes,1,primary,error,debug)){report.detail=error;return true;}if(primary.backup!=report.size_bytes/kSectorSize-1){report.detail="Primary GPT does not point to final image sector";return true;}uint64_t table_sectors=(uint64_t(primary.count)*primary.entry_size+kSectorSize-1)/kSectorSize;if(primary.table<=primary.current||primary.table>=primary.first||table_sectors>primary.first-primary.table||primary.table+table_sectors-1>=primary.backup){report.detail="Primary GPT entry table overlaps header or usable space";return true;}if(!read_gpt(file,report.size_bytes,primary.backup,backup,error,debug)){report.detail="Backup GPT: "+error;return true;}if(backup.backup!=primary.current||backup.first!=primary.first||backup.last!=primary.last||backup.count!=primary.count||backup.entry_size!=primary.entry_size||backup.table_crc!=primary.table_crc||backup.entries!=primary.entries){report.detail="Primary and backup GPT metadata disagree";return true;}uint64_t backup_sectors=(uint64_t(backup.count)*backup.entry_size+kSectorSize-1)/kSectorSize;if(backup.table<=backup.last||backup.table>=backup.current||backup_sectors>backup.current-backup.table){report.detail="Backup GPT table overlaps usable space or header";return true;}std::vector<std::pair<uint64_t,uint64_t>> ranges;for(uint32_t i=0;i<primary.count;i++){const uint8_t* entry=primary.entries.data()+size_t(i)*primary.entry_size;bool empty=true;for(int j=0;j<16;j++)if(entry[j]){empty=false;break;}if(empty)continue;uint64_t first=le64(entry+32),last=le64(entry+40);if(first<primary.first||last>primary.last||first>last){report.detail="GPT partition entry has invalid bounds";return true;}ranges.emplace_back(first,last);}std::sort(ranges.begin(),ranges.end());for(size_t i=1;i<ranges.size();i++)if(ranges[i].first<=ranges[i-1].second){report.detail="GPT partitions overlap";return true;}report.partitions=unsigned(ranges.size());report.valid=true;report.detail="Primary/backup GPT headers and tables pass CRC/consistency checks; partition ranges valid";return true;}
bool analyze_mbr(const std::array<uint8_t,512>& sector,uint64_t image_size,Report& report){report.format="MBR";unsigned active=0;std::vector<std::pair<uint64_t,uint64_t>> ranges;for(int i=0;i<4;i++){const uint8_t* entry=&sector[446+i*16];if(entry[0]!=0&&entry[0]!=0x80){report.detail="Invalid MBR boot flag";return true;}if(entry[0]==0x80)active++;uint32_t start=le32(entry+8),length=le32(entry+12);if(!length)continue;uint64_t finish=uint64_t(start)+length;if(!start||finish>image_size/kSectorSize){report.detail="MBR partition has invalid or out-of-image bounds";return true;}ranges.emplace_back(start,finish-1);}if(active>1){report.detail="Multiple active MBR partitions";return true;}std::sort(ranges.begin(),ranges.end());for(size_t i=1;i<ranges.size();i++)if(ranges[i].first<=ranges[i-1].second){report.detail="MBR partitions overlap";return true;}report.partitions=unsigned(ranges.size());report.valid=true;report.detail=std::to_string(report.partitions)+" MBR partition(s); signature, flags, bounds and overlap checks pass";return true;}
}
uint32_t crc32(const uint8_t* data,size_t size){uint32_t crc=0xffffffffu;for(size_t i=0;i<size;i++){crc^=data[i];for(int bit=0;bit<8;bit++)crc=(crc>>1)^(0xedb88320u&(0u-(crc&1u)));}return ~crc;}
bool read_at(std::ifstream& file,uint64_t offset,uint8_t* destination,size_t size){if(offset>uint64_t(std::numeric_limits<std::streamoff>::max()))return false;file.clear();file.seekg(static_cast<std::streamoff>(offset));file.read(reinterpret_cast<char*>(destination),static_cast<std::streamsize>(size));return size_t(file.gcount())==size;}
void analyze_partition_tables(std::ifstream& file,const std::array<uint8_t,512>& sector,Report& report,bool debug){if(report.size_bytes>=2*kSectorSize){std::array<uint8_t,8> signature{};if(read_at(file,kSectorSize,signature.data(),signature.size())&&std::memcmp(signature.data(),"EFI PART",8)){analyze_gpt(file,report,debug);return;}}if(sector[510]==0x55&&sector[511]==0xaa){analyze_mbr(sector,report.size_bytes,report);return;}report.detail="No valid MBR signature or GPT header found";}
}
